/* @autogenerated */
import { Injectable, inject } from '@angular/core';
import { HttpErrorResponse, HttpRequest } from '@angular/common/http';
import { NavigationEnd, Router } from '@angular/router';
import { OAuthService } from 'angular-oauth2-oidc';
import { NEVER, Observable, filter, finalize, shareReplay, switchMap, take, tap, throwError } from 'rxjs';
import { ConfirmDialogService } from '@shared/toolkit/dialog/confirm-dialog.service';
import { NotifyService } from '@shared/toolkit/notify/notify.service';

const PENDING_KEY = 'stepup.pending';
const STATE_MARK = 'stepup';
const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];

/** Lo que se recuerda durante la redirección. Nunca el cuerpo: puede llevar contraseñas o secretos. */
interface PendingStepUp {
  method: string;
  url: string;
  returnUrl: string;
}

@Injectable({ providedIn: 'root' })
export class StepUpService {
  private readonly oauth = inject(OAuthService);
  private readonly router = inject(Router);
  private readonly confirm = inject(ConfirmDialogService);
  private readonly notify = inject(NotifyService);
  private prompt?: Observable<boolean>;

  listen(): void {
    this.oauth.events.pipe(filter((e) => e.type === 'token_received')).subscribe(() => this.resumeIfPending());
  }

  /**
   * Pide confirmación y redirige al proveedor OIDC con acr_values/max_age.
   * Si el usuario cancela, la petición original falla con su error 401.
   */
  start(req: HttpRequest<unknown>, error: HttpErrorResponse, acr?: string, maxAge?: string): Observable<never> {
    // Varias peticiones pueden recibir el 401 a la vez: un único diálogo y una única redirección
    this.prompt ??= this.confirm
      .confirm({
        titleKey: 'identity.stepUp.title',
        messageKey: 'identity.stepUp.message',
        okKey: 'identity.stepUp.continue',
        cancelKey: 'identity.stepUp.cancel',
      })
      .pipe(
        tap((ok) => ok && this.redirect(req, acr, maxAge)),
        finalize(() => (this.prompt = undefined)),
        shareReplay(1),
      );
    // NEVER: la página se va al proveedor; quien llamó no debe creer que la operación terminó
    return this.prompt.pipe(switchMap((ok) => (ok ? NEVER : throwError(() => error))));
  }

  private redirect(req: HttpRequest<unknown>, acr?: string, maxAge?: string): void {
    const pending: PendingStepUp = { method: req.method, url: req.urlWithParams, returnUrl: this.router.url };
    sessionStorage.setItem(PENDING_KEY, JSON.stringify(pending));
    const params: Record<string, string> = {};
    if (acr) params['acr_values'] = acr;
    if (maxAge) params['max_age'] = maxAge;
    this.oauth.initCodeFlow(STATE_MARK, params);
  }

  private resumeIfPending(): void {
    const raw = sessionStorage.getItem(PENDING_KEY);
    sessionStorage.removeItem(PENDING_KEY);
    if (this.oauth.state !== STATE_MARK || !raw) return;
    const pending = JSON.parse(raw) as PendingStepUp;
    this.afterInitialNavigation(() => {
      this.router.navigateByUrl(pending.returnUrl).then(() => {
        // Una lectura se repite sola al volver a cargar la página; una escritura la debe repetir el usuario
        if (SAFE_METHODS.includes(pending.method.toUpperCase())) {
          this.notify.success('identity.stepUp.verified');
        } else {
          this.notify.info('identity.stepUp.repeat');
        }
      });
    });
  }

  /** El token llega durante el arranque: navegar antes de la navegación inicial sería sobrescrito por ella. */
  private afterInitialNavigation(run: () => void): void {
    if (this.router.navigated) {
      run();
    } else {
      this.router.events
        .pipe(
          filter((e) => e instanceof NavigationEnd),
          take(1),
        )
        .subscribe(run);
    }
  }
}
